import { Link, useLocation } from 'react-router-dom';
import './All.css';
import React, { useEffect, useState } from "react";
import Axios from "axios";

function All() {
  const [data, setUserList] = useState([]);
  const location = useLocation();

  const getuser = async () => {
    try {
      const response = await Axios.get("http://localhost:3002/details");
      setUserList(response.data.users || []);
    } catch (error) {
      console.error("fetching err", error);
    }
  };

  useEffect(() => {
    getuser();
  }, [location]);

  const handlDelete = async (id) => {
    const isConfirmed = window.confirm("Are you sure you want to delete this?");
    if (isConfirmed) {
      try {
        await Axios.delete(`http://localhost:3002/api/deleteuser/${id}`);
        console.log("User deleted");
        getuser();
      } catch (error) {
        console.error("Error deleting user:", error);
      }
    } else {
      console.log("Delete operation canceled");
    }
  };

  return (
    <div className="app-container">
      <div className="main-content">
        <div className="sidebar">
          {console.log("Sidebar rendered")}
          <ul>
            <li><Link to="/Dentries">Add</Link></li>
            <hr className="sidebar-line" />
            <li><Link to="/veiwfeedback">Notify</Link></li>
            <hr className="sidebar-line" />
            <li><Link to="/">All</Link></li>
          </ul>
        </div>
        <div className="table-section">
          <div className="tablebox1">
            <table border="1" className="asb">
              <thead>
                <tr>
                  <th>District</th>
                  <th>Stream & Subjects</th>
                  <th>Course</th>
                  <th>Z-Range</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {data.map((row) => (
                  <tr key={row.id || row._id}>
                    <td>{row.district || 'N/A'}</td>
                    <td>
                      <div>{row.stream || 'N/A'}</div>
                      <div>Subject 1: {row.subject1 || 'N/A'}</div>
                      <div>Subject 2: {row.subject2 || 'N/A'}</div>
                      <div>Subject 3: {row.subject3 || 'N/A'}</div>
                    </td>
                    <td>{row.course || 'N/A'}</td>
                    <td>{row.zValue1 && row.zValue2 ? `${row.zValue1} - ${row.zValue2}` : 'N/A'}</td>
                    <td>
                      <button className="update-btn">Update</button>
                      <button className="delete-btn" onClick={() => handlDelete(row._id)}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

export default All;
